// ---- The hub: commands, client to server; events, server to client ------------------------------------------------

/**
 * The live hub's commands, client → server (docs/03-protocol.md §3), at `Protocol.HubPath`. Each returns an `Ack`: what
 * happens later arrives as events on `LiveClient`. A command carries a `CommandId`; the session remembers the last 256
 * and answers a repeat with the first reply, so retrying after a reconnect never does anything twice.
 */
export interface LiveHub {
  /** Starts a session on this connection, from the device that signs `StartSessionRequest.DeviceProof`. */
  startSession(request: StartSessionRequest): Promise<Ack<SessionStarted>>;
  /** Takes up a suspended session on a new connection and replays the events after `ResumeSessionRequest.LastSeq`. */
  resumeSession(request: ResumeSessionRequest): Promise<Ack<SessionResumed>>;
  endSession(request: CommandRequest): Promise<Ack>;
  /** The interviewer's audio (PCM16 mono, 24 kHz, 100 ms frames), streamed for as long as the session runs. */
  uploadAudio(frames: StreamSubject<AudioFrame>): Promise<void>;
  /** A new interview: the documents as text (the client parses the files). */
  setContext(request: SetContextRequest): Promise<Ack>;
  setMode(request: SetModeRequest): Promise<Ack>;
  /** Answer now: the given text, or the question heard so far. */
  trigger(request: TriggerRequest): Promise<Ack>;
  ask(request: AskRequest): Promise<Ack>;
  clear(request: CommandRequest): Promise<Ack>;
  clearHeard(request: CommandRequest): Promise<Ack>;
  /** One snapshot of the session, after a (re)connect. */
  getState(): Promise<Ack<SessionSnapshot>>;
}

/**
 * The live hub's events, server → client (docs/03-protocol.md §4). Every one carries the session's sequence number
 * (`Seq`, counting from 1) and the time it was produced (`AtMs`, Unix milliseconds), so a resumed client can say what
 * it last saw.
 */
export interface LiveClient {
  status(e: StatusEvent): void;
  /** The question so far and the phrase in progress. */
  transcriptPartial(e: TranscriptUpdate): void;
  /** The question so far, a segment having just finished. */
  transcriptFinal(e: TranscriptUpdate): void;
  speechStarted(e: SpeechStartedEvent): void;
  answerStart(e: AnswerStartEvent): void;
  answerDelta(e: AnswerDeltaEvent): void;
  answerDone(e: AnswerEndEvent): void;
  /** A newer question took over before this answer finished. */
  answerCancelled(e: AnswerEndEvent): void;
  answerFailed(e: AnswerFailedEvent): void;
  cleared(e: ClearedEvent): void;
  notice(e: NoticeEvent): void;
  sessionEnded(e: SessionEndedEvent): void;
}

