// ---- Bindings to a SignalR connection, with no dependency of their own --------------------------------------------

/** What the bindings need of a connection. `@microsoft/signalr`'s `HubConnection` fits it as it is. */
export interface HubConnectionLike {
  invoke<T = unknown>(methodName: string, ...args: unknown[]): Promise<T>;
  send(methodName: string, ...args: unknown[]): Promise<void>;
  on(methodName: string, newMethod: (...args: any[]) => any): void;
  off(methodName: string, method: (...args: any[]) => any): void;
}

/**
 * A stream from the client to the hub, such as `@microsoft/signalr`'s `Subject`: `next` each item, `complete` at the
 * end.
 */
export interface StreamSubject<T> {
  next(item: T): void;
  error(err: any): void;
  complete(): void;
}

/** `LiveHub`'s commands over a connection, typed. */
export function createLiveHub(connection: HubConnectionLike): LiveHub {
  return {
    startSession: (request) => connection.invoke<Ack<SessionStarted>>(LiveHubMethods.startSession, request),
    resumeSession: (request) => connection.invoke<Ack<SessionResumed>>(LiveHubMethods.resumeSession, request),
    endSession: (request) => connection.invoke<Ack>(LiveHubMethods.endSession, request),
    uploadAudio: (frames) => connection.send(LiveHubMethods.uploadAudio, frames),
    setContext: (request) => connection.invoke<Ack>(LiveHubMethods.setContext, request),
    setMode: (request) => connection.invoke<Ack>(LiveHubMethods.setMode, request),
    trigger: (request) => connection.invoke<Ack>(LiveHubMethods.trigger, request),
    ask: (request) => connection.invoke<Ack>(LiveHubMethods.ask, request),
    clear: (request) => connection.invoke<Ack>(LiveHubMethods.clear, request),
    clearHeard: (request) => connection.invoke<Ack>(LiveHubMethods.clearHeard, request),
    getState: () => connection.invoke<Ack<SessionSnapshot>>(LiveHubMethods.getState),
  };
}

/** Calls `client` for each of `LiveClient`'s events; returns a function that stops listening. */
export function registerLiveClient(connection: HubConnectionLike, client: LiveClient): () => void {
  const handlers: [string, (...args: any[]) => void][] = [
    [LiveClientMethods.status, (e: StatusEvent) => client.status(e)],
    [LiveClientMethods.transcriptPartial, (e: TranscriptUpdate) => client.transcriptPartial(e)],
    [LiveClientMethods.transcriptFinal, (e: TranscriptUpdate) => client.transcriptFinal(e)],
    [LiveClientMethods.speechStarted, (e: SpeechStartedEvent) => client.speechStarted(e)],
    [LiveClientMethods.answerStart, (e: AnswerStartEvent) => client.answerStart(e)],
    [LiveClientMethods.answerDelta, (e: AnswerDeltaEvent) => client.answerDelta(e)],
    [LiveClientMethods.answerDone, (e: AnswerEndEvent) => client.answerDone(e)],
    [LiveClientMethods.answerCancelled, (e: AnswerEndEvent) => client.answerCancelled(e)],
    [LiveClientMethods.answerFailed, (e: AnswerFailedEvent) => client.answerFailed(e)],
    [LiveClientMethods.cleared, (e: ClearedEvent) => client.cleared(e)],
    [LiveClientMethods.notice, (e: NoticeEvent) => client.notice(e)],
    [LiveClientMethods.sessionEnded, (e: SessionEndedEvent) => client.sessionEnded(e)],
  ];
  for (const [method, handler] of handlers) {
    connection.on(method, handler);
  }

  return () => {
    for (const [method, handler] of handlers) {
      connection.off(method, handler);
    }
  };
}
